        sfx("c04_06", "act1", "Raging swollen autumn mountain river water surging violently past creaking timber bridge pilings under heavy rain, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.20, director_note="一九二七年佛蒙特大洪水"),
        dlg("c04_07", "act1", "archivist_narrator", "阿尔伯特·威尔马斯", "一切祸根都起于一九二七年十一月那场佛蒙特大洪水。暴涨的溪水冲垮偏远山谷的木桥，好几家乡村小报突然登出离奇目击：有农夫在泥流里看见几具粉红色、五英尺长、形似巨蟹却背生肉翅的怪尸！", acoustic_space="studio_warm", gap_after_s=0.26),
        dlg("c04_08", "act1", "archivist_narrator", "阿尔伯特·威尔马斯", "我当时自恃学院权威，在《阿卡姆公报》上接连发文嘲笑这是无稽之谈，断定不过是新英格兰佩纳库克印第安人流传百年的“长翼山精”传说。谁料文章刚登出三天，我就收到了一封来自佛蒙特深山的急信。", acoustic_space="studio_warm", gap_after_s=0.26),
