        dlg("c04_10", "act1", "dying_sailor", "亨利·阿克利", "[hoarsely] [seriously] 威尔马斯教授，千万别再把山里的事当成民间笑话！我叫亨利·阿克利，独居在佛蒙特黑山脚下的老农舍。那些长翅膀的怪东西是真的——它们就藏在我家屋后漆黑密林深处的秘密矿洞里！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.26),
        dlg("c04_11", "act1", "dying_sailor", "亨利·阿克利", "[hoarsely] 洪峰退去那天，我亲眼在黑山泥路上拍到三趾巨爪印，还捡到一块冰冷刺骨、刻满古怪星辰铭文的黑石头。印第安古传说没骗人——它们自称米·戈，来自太阳系最黑最冷的边缘行星犹格斯星！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.26),
        dlg("c04_12", "act1", "archivist_narrator", "阿尔伯特·威尔马斯", "阿克利不是乡野疯子，他是佛蒙特大学出身的博学藏书家，随信寄来的泥地爪印照片清晰得令人脊背发寒。更叫我心惊的是，我把黑石拓片跟密大特藏室里的上古秘卷一比对，那些铭文竟然吻合得丝毫不差！", acoustic_space="studio_warm", gap_after_s=0.26),
        sfx("c04_13", "act1", "Furious farm guard dogs barking frantically in dark wooded yard followed by splintering wooden fence boards and sudden dead silence, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.20, director_note="阿克利农场猎犬遭撕碎"),
        dlg("c04_14", "act1", "dying_sailor", "亨利·阿克利", "[terrified] [hoarsely] 教授，它们发现我在偷拍矿洞了！昨晚我养的三条最凶猛的看门猎犬冲进树林，今早只拖回几滩撕碎的皮毛和满地绿莹莹的腥臭黏液！院门外全是拍打翅膀落地的爪痕！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.26),
        dlg("c04_15", "act1", "dying_sailor", "亨利·阿克利", "[whispers] [rushed] 我冒死抱着一台便携爱迪生留声机潜伏在五月夜的祭坛林边，录下了它们跟人类眼线聚会的声音！趁邮路还没断，我这就把黑石照片和这只蜡筒寄往阿卡姆，您务必亲耳听听！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.26),
        motif("c04_16", "act1", "wax_cylinder_click", gap_after_s=0.18, director_note="在密大书房播放阿克利寄来的蜡筒"),
        dlg("c04_17", "act1", "sinister_stranger", "蜡筒人类同谋", "[coldly] [eerie] 黑山底下的矿脉已经封严了。那个多管闲事的老头阿克利，今晚必须处理干净，不能让阿卡姆的教授拿到证据。", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.22),
        dlg("c04_18", "act1", "cultist_buzzing", "蜡筒米·戈异声", "[hoarsely] [eerie] 嗡……那老头头脑敏锐……别弄碎他的颅骨……把他的大脑完整取出来，带去犹格斯星……", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.24),
        dlg("c04_19", "act1", "archivist_narrator", "阿尔伯特·威尔马斯", "[terrified] 我的手止不住地打颤！蜡筒里那个冷冰冰的人类嗓音像一把刀，可紧接着响起的那个东西——根本没有人类的肺部换气，每一字都像无数甲虫翅鞘在黑暗里高速共振！", stability=0.0, acoustic_space="studio_warm", gap_after_s=0.34),
        # --- ACT 2: Postal Infiltration + Midnight Gunfight + Cold Typewritten Reversal + Train & Noyes ---
        sfx("c04_20", "act2", "Vintage telegraph sounder tapping sporadically inside a quiet small-town post office followed by heavy boots pausing outside a wooden mail counter, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.20, director_note="邮局与电报局遭人类眼线渗透"),
        dlg("c04_21", "act2", "narrator_deep", "档案片旁白", "五月到八月间，黑山农舍陷入彻底围困。阿克利惊恐地发觉，布拉特尔伯勒镇的邮局和电报局早已换进陌生面孔——他寄给威尔马斯的黑石头包裹莫名失踪，加急电报屡屡被篡改扣押，连替他送信的邻村男孩都吓得再不敢靠近黑山。", gap_after_s=0.26),
