        dlg("c04_23", "act2", "dying_sailor", "亨利·阿克利", "[terrified] [desperately] 威尔马斯！昨晚它们砸碎了客厅玻璃冲进屋里，我举着步枪连打六发才打退它们！门廊木板上溅满臭烘烘的绿色脓液，子弹打中它们竟然发不出半点血声！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.26),
        dlg("c04_24", "act2", "dying_sailor", "亨利·阿克利", "[hoarsely] [whispers] 我终于偷听到它们抓活人的真正目的了！它们能用诡异的外科手术把活人完整的大脑切出来，泡进锃亮的金属圆筒里保鲜，接上发声器和视觉透镜，带着清醒的意识飞越冰冷无垠的星际深渊！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.28),
        dlg("c04_25", "act2", "dying_sailor", "亨利·阿克利", "[crying] [desperately] 电话线已经被剪断了！天一黑翅膀声就在屋顶盘旋，我撑不到天亮了……如果我失踪，千万别来黑山！直接把蜡筒和我的信全部烧掉！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.30),
        dlg("c04_26", "act2", "archivist_narrator", "阿尔伯特·威尔马斯", "我急得坐立难安，正准备连夜报警赶往佛蒙特。可就在整整一周杳无音信之后，我的办公桌上竟然静静躺着一封崭新的佛蒙特来信——诡异的是，整封信不再是手写，而是用打字机敲得工整冰冷。", acoustic_space="studio_warm", gap_after_s=0.26),
        sfx("c04_27", "act2", "Brisk mechanical vintage typewriter keys clacking steadily with cold precision followed by a sharp metal carriage return bell chime, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.20, director_note="突如其来的打字机冰冷反转信"),
        dlg("c04_28", "act2", "cosmic_monolith", "打字机来信内容", "[coldly] 亲爱的威尔马斯教授：请原谅我此前神经衰弱造成的荒唐误会。外星来客其实无比睿智友善，早已与我和解并向我展示了宇宙奥秘。请您务必带上我先前寄出的全部信件、照片和蜡筒，亲临寒舍共赏奇迹。亨利·阿克利谨上。", stability=1.0, acoustic_space="memory_echo", gap_after_s=0.28),
        dlg("c04_29", "act2", "archivist_narrator", "阿尔伯特·威尔马斯", "[seriously] 信尾甚至没有手写签名，连标点节奏都透着一股机械的生硬！理智告诉我这分明是陷阱，可那股想亲眼揭开星际真相的疯狂学者好奇心，竟然压倒了一切恐惧。", acoustic_space="studio_warm", gap_after_s=0.26),
        sfx("c04_30", "act2", "1920s passenger steam train wheels clacking rhythmically over steel mountain rails followed by a mournful distant train whistle in autumn twilight, pure foley, no human voice", duration_seconds=3.2, gap_after_s=0.20, director_note="乘火车北上佛蒙特布拉特尔伯勒"),
        dlg("c04_31", "act2", "narrator_deep", "档案片旁白", "一九二八年九月十二日，威尔马斯提着装满全部信件与蜡筒的黑色公文包，乘火车北上佛蒙特布拉特尔伯勒。天色刚暗，站台阴影里走出一个神情僵硬的中年司机。", gap_after_s=0.24),
        sfx("c04_32", "act2", "Old 1920s Ford sedan engine rattling steadily up a steep rocky unpaved mountain lane surrounded by dense rustling black pines at dusk, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.20, director_note="神秘司机诺伊斯开车接进黑山"),
        dlg("c04_33", "act2", "sinister_stranger", "司机诺伊斯", "[coldly] 威尔马斯教授吧？我叫诺伊斯，阿克利先生请我来接您。公文包给我放后备箱吧——您把蜡筒和旧信都带齐了吗？", stability=0.0, gap_after_s=0.22),
        dlg("c04_34", "act2", "archivist_narrator", "阿尔伯特·威尔马斯", "[calmly] 谢谢，公文包我抱着就好。诺伊斯先生，您的口音怎么听着那么耳熟？我们以前在哪儿见过吗？", gap_after_s=0.22),
        dlg("c04_35", "act2", "archivist_narrator", "阿尔伯特·威尔马斯", "轿车钻进越来越陡的碎石山道，两旁遮天蔽日的黑松压得人喘不过气。沿途几栋石砌老农舍早就塌了屋顶，荒草丛生，整片山谷死一般寂静，连一声犬吠都听不见。", acoustic_space="studio_warm", gap_after_s=0.24),
        dlg("c04_36", "act2", "sinister_stranger", "司机诺伊斯", "[coldly] [eerie] 教授记错了吧，我常年在黑山一带帮工。到了，前面那栋没点灯的木头农舍就是阿克利家。我把车停在谷仓后头，您自己推门进去吧。", stability=0.0, gap_after_s=0.24),
        dlg("c04_37", "act2", "archivist_narrator", "阿尔伯特·威尔马斯", "[whispers] [terrified] 车门关上的那一秒，我浑身一激灵——诺伊斯刚才那副冰冷腔调，跟蜡筒里那个发号施令的人类同谋，简直一模一样！可回头看去，山路已经彻底吞没在漆黑密林里了。", stability=0.0, acoustic_space="mental_realm", gap_after_s=0.34),
