        sfx("c04_38", "act3", "Distant midnight crickets outside an isolated dark country farmhouse as a heavy wooden porch door creaks slowly inward revealing a slow ticking grandfather clock, pure foley, no human voice", duration_seconds=3.2, gap_after_s=0.20, director_note="推开漆黑孤屋客厅门"),
        dlg("c04_39", "act3", "archivist_narrator", "阿尔伯特·威尔马斯", "我硬着头皮推开前门。整栋农舍一盏灯也没点，只有壁炉余烬透出一星微红。屋角那张高背扶手椅的浓重阴影里，端坐着一个裹着厚绒睡袍、动也不动的人影。", gap_after_s=0.26),
        dlg("c04_40", "act3", "cultist_buzzing", "黑暗中的阿克利", "[hoarsely] [eerie] 欢迎光临，威尔马斯教授……请原谅屋里黑。我最近突发重度哮喘，眼睛见不得光，喉咙也发炎了，只能这样压低气声跟您交谈。", stability=0.0, gap_after_s=0.26),
        dlg("c04_41", "act3", "archivist_narrator", "阿尔伯特·威尔马斯", "[calmly] 阿克利先生，您声音听着确实虚弱得厉害。可我站在门口总觉得奇怪——您之前信里说它们在围攻农舍，怎么几天工夫就全变成误会了？", gap_after_s=0.24),
        dlg("c04_42", "act3", "cultist_buzzing", "黑暗中的阿克利", "[hoarsely] [softly] 是我太狭隘了，教授……人类对宇宙的认知实在可笑。从沉没的拉莱耶到星海边缘的犹格斯星，他们知晓万物本源。先请把公文包放到书桌上吧，信件和蜡筒都在里头吗？", stability=0.0, gap_after_s=0.26),
