        dlg("c04_48", "act3", "cosmic_monolith", "B-67金属脑罐", "[solemn] 晚上好，威尔马斯教授。不必恐惧这只冷冰冰的金属外壳。我曾经和你一样，是一名受困于脆弱肉身与百年寿命的地球学者。", stability=1.0, acoustic_space="mental_realm", gap_after_s=0.26),
