        dlg("c05_08", "act1", "dean_armitage", "亨利·阿米蒂奇博士", "所有骇人听闻的灾难，都发端于山坡孤宅里的沃特雷一家。老巫师沃特雷整日关起门翻读发霉的黑魔法典籍，他三十五岁的畸形白化病女儿拉维妮娅从不出嫁，却在一九一三年圣烛节清晨，突然生下一个没有父亲的男婴。", acoustic_space="studio_warm", gap_after_s=0.26),
