        dlg("c05_20", "act2", "dean_armitage", "亨利·阿米蒂奇博士", "一九二八年五月，那个八英尺高的恐怖青年第一次踏进了我掌管的密斯卡托尼克大学图书馆。他从破旧帆布袋里掏出一本残缺不全的英译本《死灵之书》，粗哑着嗓子要求核对馆里上锁的拉丁文孤本。", acoustic_space="studio_warm", gap_after_s=0.26),
