        dlg("c05_34", "act2", "dean_armitage", "亨利·阿米蒂奇博士", "不到一小时，这具非人躯壳就在所有医生眼前滋滋化成一滩散发腥臭的粘稠白浆，蒸发得一干二净。我连夜带人赶赴敦威治查抄沃特雷老宅，从乱纸堆里翻出了威尔伯用古老密码写成的厚厚日记。", acoustic_space="studio_warm", gap_after_s=0.24),
