        motif("c06_05", "act1", "wax_cylinder_click", gap_after_s=0.22, director_note="档案启封"),
        dlg("c06_06", "act1", "female_archivist", "阿卡姆档案员", "[seriously] 档案编号零零六：《疯狂山脉》。一九三一年春，密斯卡托尼克大学地质学教授威廉·戴尔公开违背校方最高保密协议，在听证会前夜向档案室递交了这份震惊学界的南极真相。", acoustic_space="studio_warm", gap_after_s=0.26),
        dlg("c06_07", "act1", "archivist_narrator", "威廉·戴尔教授", "[solemn] 我之所以被迫打破沉默，把一九三〇年那场噩梦公之于众，只为了一个生死攸关的请求——无论付出多大代价，必须立刻叫停史塔克威瑟莫尔探险队！绝不许他们把钻头扎进南极内陆的高原冰层！", acoustic_space="studio_warm", gap_after_s=0.28),
        sfx("c06_08", "act1", "Heavy steel polar icebreaker hull crunching steadily through thick Antarctic pack ice followed by a powerful mechanical thermal rock drill boring smoothly into frozen bedrock, pure foley, no human voice", duration_seconds=3.2, gap_after_s=0.20, director_note="一九三〇年密大南极科考队满怀壮志启程"),
        dlg("c06_09", "act1", "archivist_narrator", "威廉·戴尔教授", "去年九月，我们密斯卡托尼克大学南极科考队意气风发地启航南下。两艘破冰船、四架专为极地改装的滑雪翼双翼机，还有帕布迪发明的轻便热熔深层钻机，全队二十名学者立志解开南极古地质之谜。", acoustic_space="studio_warm", gap_after_s=0.26),
        dlg("c06_10", "act1", "archivist_narrator", "威廉·戴尔教授", "极地午夜的惨白阳光横扫无边冰原，远方地平线常浮现奇异的海市蜃楼，隐约勾勒出不该存在于地球的巨石城廓。我们当初只当那是光线折射的幻觉。", acoustic_space="studio_warm", gap_after_s=0.24),
        dlg("c06_11", "act1", "archivist_narrator", "威廉·戴尔教授", "起初一切顺利。直到我们在麦克默多湾钻出五亿年前的太古代板岩岩芯——上面赫然印着一串一英尺长、带着奇异辐射条纹的三角足印！生物学家莱克教授当场眼睛发亮，立刻拍案而起。", acoustic_space="studio_warm", gap_after_s=0.26),
        dlg("c06_12", "act1", "dean_armitage", "莱克教授", "[excited] [seriously] 戴尔！这绝不是已知的任何古生代动物！五亿年前南极还温暖如春，这串三角脚印指向西北内陆——给我一架飞机和十一名精锐队员，我要飞去黑山源头挖出完整的化石！", gap_after_s=0.26),
        motif("c06_13", "act1", "morse_telegraph_distress", gap_after_s=0.18, director_note="莱克前锋营地第一封短波急电"),
        dlg("c06_14", "act1", "dean_armitage", "莱克教授电报", "[excited] 戴尔！我们往西北飞了三百英里，撞见一道高耸入云、漆黑如墨的锯齿状巨峰！海拔绝对比喜马拉雅山还高！我们在山脚地下溶洞钻出了前所未有的十四具桶状史前样本！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.26),
        sfx("c06_15", "act1", "Frantic Antarctic sled dogs barking wildly outside flapping canvas expedition tents inside rising polar gale winds, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.20, director_note="雪橇犬对融冰样本疯狂狂吠"),
        dlg("c06_16", "act1", "panicked_witness", "莱克营地电报员", "[rushed] [terrified] 戴尔教授，莱克刚解剖完一具破损样本——这东西有高度发达的五叶大脑、星状神经节和坚韧橡胶皮，半植物半动物！切口还渗出淡淡绿汁，像昨天刚冻住一样新鲜！可营地里的雪橇犬全发了疯，拼命想咬碎帐篷里的完好样本！", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.26),
        dlg("c06_17", "act1", "dean_armitage", "莱克教授电报", "[hoarsely] [rushed] 黑色巨峰风口刮来一场怪风，吹过山脊像成千上万根巨型长笛在凄厉鸣叫！营地帐篷快掀翻了，电台电压剧降——等等，标本帐篷怎么被从里面划开了——", stability=0.0, acoustic_space="memory_echo", gap_after_s=0.20),
        sfx("c06_18", "act1", "Sudden piercing shortwave signal drop dissolving into cold white static followed by airplane skis scraping harshly across frozen wind-packed Antarctic snow, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.20, director_note="电台失联后戴尔与丹佛斯飞抵惨烈营地"),
        dlg("c06_19", "act1", "narrator_deep", "档案片旁白", "整整两天呼叫毫无回应。风暴刚歇，戴尔教授与年轻博学的研究生丹佛斯驾机赶抵莱克前锋营地。眼前的惨状，让两位见过世面的学者瞬间僵死在零下四十度的雪地里。", gap_after_s=0.24),
        dlg("c06_20", "act1", "young_investigator", "丹佛斯", "[gasps] [terrified] 教授……莱克和十名队员全都死了！可这根本不是野兽撕咬——他们的胸腹被切开得像外科教科书一样精准，连雪橇犬也被同样解剖了！", stability=0.0, gap_after_s=0.22),
        sfx("c06_21", "act1", "Freezing polar wind flipping stiff frost-stiffened canvas expedition field notebook pages resting in snow beside shattered glass vials, pure foley, no human voice", duration_seconds=2.4, gap_after_s=0.18, director_note="翻出莱克冻僵的现场实验笔记"),
        dlg("c06_22", "act1", "young_investigator", "丹佛斯", "[whispers] [terrified] 我在雪里捡到莱克没写完的实验本！最后一行冻住的字迹写着：暖炉融化寒冰后，那八具完好样本的膜翼突然自己抽动了起来！", stability=0.0, gap_after_s=0.24),
        dlg("c06_23", "act1", "archivist_narrator", "威廉·戴尔教授", "[hoarsely] [seriously] 快数标本帐篷！十四具桶状怪物，最完好的八具连同我们的汽油、雪橇、解剖图谱和手电筒，全被有条理地打包带走了！而那六具受损破败的样本，竟然被人直立埋进了雪地里——上面插着六座工整的五角星雪墓！", stability=0.0, gap_after_s=0.30),
        # --- ACT 2: Flight Across the Black Mountains + 50-Million-Year-Old Cyclopean City ---
        dlg("c06_24", "act2", "archivist_narrator", "威廉·戴尔教授", "绝不是野兽干的——能工整掩埋同伴、还能拿走人体解剖书的，必定拥有极高智慧！我跟丹佛斯做了一个此生最疯狂的决定：加满备用航空汽油，趁晴空驾机直接飞越那道漆黑风口！", acoustic_space="studio_warm", gap_after_s=0.26),
        sfx("c06_25", "act2", "Vintage ski-equipped biplane engine droning hard in thin sub-zero polar air while eerie flute-like wind pipes hauntingly past taut metal wing struts, pure foley, no human voice", duration_seconds=3.2, gap_after_s=0.20, director_note="冒险驾机翻越超越珠峰的黑山风口"),
        dlg("c06_26", "act2", "young_investigator", "丹佛斯", "[terrified] [shouting] 教授，快看海拔表！我们已经爬升到两万四千英尺，可眼前这些漆黑锯齿状的巨峰还高出我们一万多英尺——它比珠穆朗玛峰还要高出整整一截！", stability=0.0, gap_after_s=0.24),
        dlg("c06_27", "act2", "young_investigator", "丹佛斯", "[gasps] [terrified] 机身在剧烈颠簸！风口吹出来的声音像魔鬼吹笛子一样！等等——往左舷绝壁下面看！那些方方正正砌在峭壁上的绿黑色石块……那不是天然岩石，那是人工建的城堡壁垒！", stability=0.0, gap_after_s=0.26),
        motif("c06_28", "act2", "polar_blizzard_gust", gap_after_s=0.20, director_note="穿出风口云雾骤见亿年死城"),
        dlg("c06_29", "act2", "narrator_deep", "档案片旁白", "[dramatically] 双翼机险之又险穿出漆黑山口的刹那，耀眼的极地低空斜阳扑面而来。云雾散尽，下方一望无际的冰封高原上，赫然铺开一座令人类文明显得如蚁穴般渺小的亿年黑色巨石死城！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.26),
        dlg("c06_30", "act2", "archivist_narrator", "威廉·戴尔教授", "[solemn] [softly] 五角星圆锥塔、无窗巨石金字塔、凌空横跨深谷的玄武岩天桥……整座城市延绵上百英里，建筑尺度宏伟到令人头晕目眩。从地质断层看，早在人类猿祖出现前五千万年，它就已经矗立在这里了！", acoustic_space="vast_hall", gap_after_s=0.26),
        sfx("c06_31", "act2", "Airplane skis grinding smoothly across hard windswept plateau snow followed by heavy crunching crampon boots echoing inside a colossal cavernous frozen basalt temple hall, pure foley, no human voice", duration_seconds=3.2, gap_after_s=0.20, director_note="降落死城边缘步入冰封神殿"),
        dlg("c06_32", "act2", "archivist_narrator", "威廉·戴尔教授", "我们在死城外围平滑冰面上着陆，背上强光手电与地质锤，穿过一排排诡异的五角星拱廊，钻进一座半埋在万年积雪里的宏伟神殿。外界暴风雪声骤然隔绝，只剩永恒零下五十度的绝对死寂。", acoustic_space="vast_hall", gap_after_s=0.24),
        dlg("c06_33", "act2", "archivist_narrator", "威廉·戴尔教授", "厅内没有半件给人类双腿设计的桌椅，全是为长着星形触手与折叠蝠翼的居民打造的低矮斜台、五角石盆与倾斜巨门。万年严寒把一切封存得宛如昨日。", acoustic_space="vast_hall", gap_after_s=0.24),
        dlg("c06_34", "act2", "young_investigator", "丹佛斯", "[whispers] [curious] 教授，把光束往上移！所有门框和走廊竟然全都严格遵循五角对称！整面三十英尺高的黑曜石石壁上，从头到尾刻满了极其精妙的连环浮雕壁画——上面刻着的主角，全都是莱克营地挖出来的五角桶状生物！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.30),
        # --- ACT 3: Elder Things Murals + Subterranean Tunnel + Beheaded Elder Things + Shoggoth Pursuit ---
        dlg("c06_35", "act3", "archivist_narrator", "威廉·戴尔教授", "我们屏息沿着拱廊一间间走过，借着手电强光，像翻阅一部刻在石头上的星球创世史诗，逐幅读懂了这个伟大失落文明的兴衰。", acoustic_space="studio_warm", gap_after_s=0.24),
        dlg("c06_36", "act3", "cosmic_monolith", "第一幅史诗壁画", "[solemn] 十亿年前，地球尚是一片滚烫荒芜的死海。古老者展开五片星际膜翼，自深空以太降临南极浅海。他们以精湛的生物工学捏造出地球最初的细胞生命，部分充作食粮，部分任其演化成漫山遍野的生灵与人类远祖。", stability=1.0, acoustic_space="mental_realm", gap_after_s=0.28),
        dlg("c06_37", "act3", "young_investigator", "丹佛斯", "[whispers] [terrified] 教授……按照这幅浮雕的意思，地球上所有生物包括我们人类，最初都只是这群天外客随手做实验的副产品？！再看下一幅——那些泡在海底搬巨石的黑色巨泥是什么？", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.24),
        dlg("c06_38", "act3", "cosmic_monolith", "第二幅史诗壁画", "[solemn] 为搬运万吨玄武巨石，古老者创造了原生质奴仆——修格斯。它们如十五英尺高的沸腾黑泥，能随催眠指令凭空化出眼珠、触手与器官，替主人筑起横跨海底与陆地的无双巨城。", stability=1.0, acoustic_space="mental_realm", gap_after_s=0.28),
        dlg("c06_39", "act3", "cosmic_monolith", "第三幅史诗壁画", "[solemn] 漫长纪元中，古老者曾与海底克苏鲁眷族及天外米·戈血战，却在鼎盛之际迎来致命反噬——修格斯竟悄悄生出独立贪婪的智慧！那场席卷大洋的奴隶叛乱险些覆灭文明，最终靠分子裂解兵器才勉强镇压。", stability=1.0, acoustic_space="mental_realm", gap_after_s=0.28),
        motif("c06_40", "act3", "abyssal_sub_bass_hum", gap_after_s=0.20, director_note="壁画笔触骤然惊恐，地底传来深沉震颤"),
        dlg("c06_41", "act3", "archivist_narrator", "威廉·戴尔教授", "[seriously] 丹佛斯，你看最后几间大厅的浮雕！刻工突然变得粗劣慌乱！随着百万年前大冰期覆盖南极，古老者被迫放弃地面宏城，沿着一条巨大的倾斜隧道撤往地底深处的温暖暗海。", acoustic_space="vast_hall", gap_after_s=0.24),
        dlg("c06_42", "act3", "young_investigator", "丹佛斯", "[whispers] [terrified] 可看壁画最边缘——他们最恐惧的不只是学会模仿主人笛声的地底修格斯，还有西边那道更高、更黑的紫色山脉！连古老者自己都严禁踏足黑山彼端，只敢在石头上留下颤抖的警示符！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.26),
        dlg("c06_43", "act3", "archivist_narrator", "威廉·戴尔教授", "[softly] [solemn] 我终于懂了……丹佛斯，瞧他们壁画里的艺术、科学与悲欢。无论外形多么异类，他们曾是真正的科学家与文明建造者。", acoustic_space="vast_hall", gap_after_s=0.22),
        dlg("c06_44", "act3", "archivist_narrator", "威廉·戴尔教授", "[solemn] 莱克营地苏醒的那八具古老者根本不是恶魔，他们只是被冰封百万年刚醒来，出于好奇解剖了我们的队员，再带着好奇的战利品踏上了回家的路。", acoustic_space="vast_hall", gap_after_s=0.26),
        sfx("c06_45", "act3", "Heavy boots descending cautiously along a slick sloping subterranean black stone corridor with eerie faint musical piping echoing upward from abyssal darkness, pure foley, no human voice", duration_seconds=3.2, gap_after_s=0.20, director_note="深入倾斜地底冰道发现营地遗物"),
        dlg("c06_46", "act3", "young_investigator", "丹佛斯", "[whispers] [terrified] 教授，前面倾斜冰道上散落着莱克营地的红铅笔、手电电池和拉雪橇的麻绳！石壁上怎么沾满一层新鲜发亮的漆黑黏液？苏醒的古老者确实刚沿着这条暗道往下走了——等等，前面拐角躺着什么？", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.22),
        sfx("c06_47", "act3", "Heavy metal flashlight slipping from trembling grip and clattering loudly across jagged frozen cave stone floor, pure foley, no human voice", duration_seconds=2.4, gap_after_s=0.18, director_note="拐角发现被斩首的古老者与白化巨企鹅"),
        dlg("c06_48", "act3", "archivist_narrator", "威廉·戴尔教授", "[gasps] [terrified] 天呐！是四具从莱克营地逃回来的古老者！他们全死了——五角海星脑袋被人用恐怖蛮力生生拧断斩首，断口上浸满散发刺鼻沥青恶臭的黏滑黑泥！连那几只六英尺高的盲眼白化巨企鹅都正惊慌地朝咱们擦身狂奔！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.26),
        sfx("c06_49", "act3", "Vast subterranean ice tunnel shaking with a horrific rising viscous bubbling thundering mass rushing rapidly forward like an unstoppable underground subway train in pitch darkness, pure foley, no human voice", duration_seconds=3.4, gap_after_s=0.16, director_note="地底沸腾修格斯如列车狂潮逼近"),
        dlg("c06_50", "act3", "young_investigator", "丹佛斯", "[terrified] [whispers] 教授……地窟深处涌上来的沥青恶臭快让人窒息了！手电光束都在震动！黑暗里那阵像高速地铁一样滚过来的黏腻轰鸣是什么？！有什么东西顺着冰道追上来了！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.18),
        dlg("c06_51", "act3", "outer_god_echo", "修格斯狂潮", "[dramatically] [solemn] 泰克利——利！泰克利——利！", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.18),
        dlg("c06_52", "act3", "archivist_narrator", "威廉·戴尔教授", "[terrified] [shouting] 跑！拼命往回跑！那是古老者当年留下的奴仆——活着的修格斯！它正学着死去主人的笛声惨叫！十五英尺高的一团沸腾黑泥，塞满了整条冰道，浑身鼓起成千上万只燃烧的绿眼泡，直扑咱们撞过来了！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.22),
        sfx("c06_53", "act3", "Desperate frantic crampon boots sprinting blindly up frozen stone passages while a colossal wet gelatinous rumbling shockwave shakes ancient cavern walls directly behind them, pure foley, no human voice", duration_seconds=3.4, placement="overlay_next", gap_after_s=0.18, director_note="生死冲刺逃离修格斯追杀"),
        dlg("c06_54", "act3", "young_investigator", "丹佛斯", "[desperately] [shouting] 它冲破石门了！左转！往咱们进来时做的纸屑路标冲！看见天光了——外面就是飞机！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.26),
        # --- ACT 4: Takeoff + Danforth's One Forbidden Glance Back + Season 1 Grand Finale ---
        sfx("c06_55", "act4", "Biplane cold engine sputtering urgently twice before catching into a full-throttle propeller roar as skis lift sharply off jagged snow into howling mountain pass winds, pure foley, no human voice", duration_seconds=3.6, gap_after_s=0.20, director_note="强行点火起飞冲出黑色风口"),
        dlg("c06_56", "act4", "narrator_deep", "档案片旁白", "两人连滚带爬撞出冰洞，在冻僵的油门嘶吼中强行拉升起飞！飞机擦着五角星黑塔尖端冲回云海，拼尽全力重新钻进那道如笛呜咽的黑色风口。机翼在剧烈下沉气流中嘎吱作响，戴尔死死盯住前方仪表盘，严令丹佛斯绝不许回头。", gap_after_s=0.26),
        dlg("c06_57", "act4", "archivist_narrator", "威廉·戴尔教授", "[shouting] 丹佛斯！死死抓紧安全带，眼睛看前面！西边那是古老者壁画上连提都不敢提的紫色黑山彼端——绝对别回头！", stability=0.0, gap_after_s=0.20),
